// DEV_RIO_101 Evidence Build — 実運用
// 入力（テーマ/読者像）を受け取る。未指定時のみデフォルト値を使う。
const i = $input.first().json;
return [{ json: {
  experiment_id: i.experiment_id ?? 'exp-001',
  theme: i.theme ?? '店舗の固定費/決済手数料の見直し',
  audience: i.audience ?? '小規模店舗経営者(飲食・美容)',
  raw_sources: i.raw_sources ?? []
} }];

// Anthropic向けリサーチ依頼プロンプトを組み立てる。
// 出力は必ずJSONのみ、source_typeは'estimation'（一般知識に基づく推測）に限定させ、
// 実測データであるかのような断定を防ぐ（捏造禁止の原則を守る）。
const i = $input.first().json;
const prompt = `あなたは市場調査アシスタントです。以下のテーマについて、一般的に知られている傾向・想定される顧客の悩み・競合となりうるアプローチを、日本語で整理してください。

テーマ: ${i.theme}
想定読者/顧客: ${i.audience}

出力は必ず次のJSON形式のみで返してください（前後に説明文・コードブロック記号を付けない）。
{
  "facts": [
    { "claim": "string", "value": null, "source_type": "estimation", "source_url": null }
  ]
}

注意:
- source_type は必ず "estimation" のみを使用すること（実測・確認済みの事実であるかのような値は禁止）。
- claim は一般的な傾向としてわかる書き方にし、具体的な社名・個人名・断定的な数値は書かないこと。
- facts は3〜6件返すこと。`;
const anthropic_body = {
  model: 'claude-sonnet-4-5',
  max_tokens: 1024,
  messages: [ { role: 'user', content: prompt } ]
};
return [{ json: { ...i, research_prompt: prompt, anthropic_body } }];

// Anthropicの応答をパースする。失敗時・エラー時は捏造せず source_type='unknown' として明示する。
const input = $input.first().json;
const o = $('Build Research Prompt').first().json;
let facts = null;
let parse_error = null;

if (input.error) {
  parse_error = 'anthropic_api_error: ' + JSON.stringify(input.error).slice(0, 300);
} else {
  try {
    const text = input.content && input.content[0] && input.content[0].text;
    if (!text) throw new Error('no text in response');
    const cleaned = text.trim().replace(/^```json\s*/i, '').replace(/```\s*$/, '');
    const parsed = JSON.parse(cleaned);
    if (!Array.isArray(parsed.facts) || parsed.facts.length === 0) throw new Error('facts missing/empty');
    facts = parsed.facts.map(f => ({
      claim: f.claim ?? '（応答からclaimを取得できず）',
      value: f.value ?? null,
      source_type: f.source_type === 'estimation' ? 'estimation' : 'unknown',
      source_url: f.source_url ?? null
    }));
  } catch (e) {
    parse_error = 'parse_failed: ' + e.message;
  }
}

if (!facts) {
  facts = [{ claim: '需要・競合・報酬条件は未取得（AI応答の取得/解析に失敗）', value: null, source_type: 'unknown', source_url: null }];
}

return [{ json: {
  experiment_id: o.experiment_id,
  theme: o.theme,
  audience: o.audience,
  raw_sources: o.raw_sources,
  research_facts: facts,
  research_error: parse_error
} }];

// Evidence Pack 組み立て。未取得・未検証の事実は source_type='unknown'（捏造しない）。
// raw_sourcesがあれば優先し、AIリサーチの推測(estimation)はそれを補完する形で合成する。
const o = $input.first().json;
const execId = $execution?.id ?? 'run';
const rawFacts = (o.raw_sources && o.raw_sources.length)
  ? o.raw_sources.map(s => ({ claim: s.claim, value: s.value ?? null, source_type: s.source_type ?? 'unknown', source_url: s.source_url ?? null }))
  : [];
const facts = rawFacts.length ? rawFacts.concat(o.research_facts || []) : (o.research_facts || [{ claim: '需要・競合・報酬条件は未取得', value: null, source_type: 'unknown', source_url: null }]);
return [{ json: {
  evidence_pack_id: 'ev-' + execId,
  experiment_id: o.experiment_id,
  sources: (o.raw_sources || []).map(s => s.source_url).filter(Boolean),
  facts,
  notes: o.research_error ? ('AIリサーチ取得に問題あり: ' + o.research_error) : 'AIリサーチ(Anthropic API)による一般的傾向の推測を含む。実測データではない。',
  assets: []
} }];
